<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Archive, ArrowRightLeft, AlertCircle, Check, ChevronDown, Clock3, FolderOpen, HardDrive, LoaderCircle, Plus, RefreshCw, RotateCcw, ShieldAlert, Trash2, X } from 'lucide-vue-next'
import { api } from '../api'
import BaseModal from '../components/BaseModal.vue'
import SquirrelMark from '../components/SquirrelMark.vue'
import { notify, store } from '../store'
import type { Connection } from '../types'

type Tab = 'backup' | 'migration'
interface BackupJob { id:string; name:string; connectionId:string; localPath:string; remotePrefix:string; exclude:string[]; scheduleMinutes:number; retainRecent:number; retainDaily:number; retainMonthly:number; enabled:boolean; lastRun?:string; status?:string; detail?:string; created?:string }
interface BackupFile { path:string; sha256:string; size:number; state:string; error?:string }
interface BackupPreview { jobId:string; token:string; created:string; files:BackupFile[]; bytes:number; excluded:number }
interface BackupSnapshot { id:string; jobId:string; started:string; completed?:string; status:string; filesTotal:number; filesDone:number; filesFailed:number; bytesTotal:number; error?:string; files?:BackupFile[] }
interface BackupCleanupObject { path:string; etag:string; size:number; kind:string }
interface BackupCleanupPreview { jobId:string; snapshotId:string; token:string; created:string; status:string; objects:BackupCleanupObject[]; bytes:number }
interface BackupCleanupResult { jobId:string; snapshotId:string; status:string; deleted:string[]; remaining:string[]; errors:string[] }
interface MigrationJob { id:string; name:string; sourceConnection:string; sourcePrefix:string; targetConnection:string; targetPrefix:string; exclude:string[]; overwrite:boolean; enabled:boolean; created?:string }
interface MigrationItem { sourcePath:string; targetPath:string; sourceEtag:string; sourceSize:number; sourceHash?:string; destBeforeEtag?:string; destAbsent:boolean; destEtag?:string; state:string; error?:string }
interface MigrationPreview { jobId:string; token:string; created:string; sourceFiles:number; conflicts:number; bytes:number; items:MigrationItem[] }
interface MigrationRun { id:string; jobId:string; state:string; started:string; updated:string; filesTotal:number; filesDone:number; filesFailed:number; cancelled:boolean; detail?:string }
interface CleanupPreview { runId:string; token:string; created:string; items:MigrationItem[] }

const tab=ref<Tab>('backup')
const busy=ref('')
const loading=ref(false)
const pageError=ref('')
const backupJobs=ref<BackupJob[]>([])
const snapshots=ref<BackupSnapshot[]>([])
const snapshotsLoading=ref(false)
const snapshotsError=ref('')
const lastBackupResult=ref<BackupSnapshot|null>(null)
const backupCleanupTarget=ref<BackupSnapshot|null>(null)
const backupCleanupError=ref('')
const backupCleanupPreview=ref<BackupCleanupPreview|null>(null)
const backupCleanupResult=ref<BackupCleanupResult|null>(null)
const selectedBackup=ref('')
const backupPreview=ref<BackupPreview|null>(null)
const backupFormOpen=ref(false)
const backupEditId=ref('')
const backupConfirm=ref<{kind:'delete'|'restore';id:string;name:string;remote?:boolean;connectionId?:string;prefix?:string}|null>(null)
const backupForm=reactive({name:'',connectionId:'',localPath:'',remotePrefix:'',exclude:'',scheduleMinutes:0,retainRecent:10,retainDaily:7,retainMonthly:12,enabled:true})
const remoteConnection=ref('')
const remotePrefix=ref('')
const remoteSnapshots=ref<BackupSnapshot[]>([])
const remoteLoading=ref(false)
const remoteError=ref('')

const migrationJobs=ref<MigrationJob[]>([])
const migrationRuns=ref<MigrationRun[]>([])
const runsLoading=ref(false)
const runsError=ref('')
const selectedMigration=ref('')
const migrationPreview=ref<MigrationPreview|null>(null)
const cleanupPreview=ref<CleanupPreview|null>(null)
const migrationFormOpen=ref(false)
const migrationEditId=ref('')
const migrationConfirm=ref<{kind:'delete'|'start'|'cancel'|'cleanup';id:string;name:string}|null>(null)
const migrationForm=reactive({name:'',sourceConnection:'',sourcePrefix:'',targetConnection:'',targetPrefix:'',exclude:'',overwrite:false})
let snapshotsRequest=0
let runsRequest=0
const eligible= computed(()=>store.data.connections.filter(c=>['s3','webdav','demo'].includes(c.kind)))
const migrationTargets=computed(()=>eligible.value.filter(c=>c.kind!=='demo'||store.data.connections.find(x=>x.id===migrationForm.sourceConnection)?.kind==='demo'))
const selectedJob=computed(()=>backupJobs.value.find(j=>j.id===selectedBackup.value))
const selectedMigrationJob=computed(()=>migrationJobs.value.find(j=>j.id===selectedMigration.value))
const canRunBackup=computed(()=>!!backupPreview.value&&backupPreview.value.jobId===selectedBackup.value)
const migrationProgress=(r:MigrationRun)=>r.filesTotal?Math.min(100,Math.floor((r.filesDone+r.filesFailed)*100/r.filesTotal)):0
const fmt=(n:number)=>{if(!n)return'0 B';const units=['B','KB','MB','GB','TB'];let v=n,i=0;while(v>=1024&&i<units.length-1){v/=1024;i++}return`${v.toFixed(i===0||v>=10?0:1)} ${units[i]}`}
const time=(v?:string)=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(+d)?v:new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
const connName=(id:string)=>store.data.connections.find(c=>c.id===id)?.name||'连接不可用'
const statusLabels:Record<string,string>={ready:'待运行',running:'运行中',queued:'排队中',cancel_requested:'正在取消',complete:'已完成',completed:'已完成',cleaned:'远端残余已清理',partial:'部分完成',failed:'失败',error:'失败',waiting:'等待中',paused:'已暂停',done:'已完成',planned:'待迁移',conflict:'冲突',source_deleted:'源已清理',source_delete_failed:'源清理失败',cleanup_uncertain:'源清理待核对',cancelled:'已取消',uncertain:'待核对',deleted:'已删除',pending:'待处理',skipped:'已跳过'}
const statusLabel=(state:string)=>statusLabels[state]||state||'未知'
const statusClass=(state:string)=>['ready','complete','completed','done','source_deleted'].includes(state)?'green':['failed','error','deleted','source_delete_failed'].includes(state)?'red':['partial','conflict','uncertain','cleanup_uncertain'].includes(state)?'amber':['running','queued','cancel_requested'].includes(state)?'blue':'gray'
const migrationItemLabel=(state:string)=>state==='ready'?'可迁移':statusLabel(state)
async function loadAll(){loading.value=true;pageError.value='';try{const [b,m]=await Promise.all([api.get<BackupJob[]>('/api/backups'),api.get<MigrationJob[]>('/api/migrations')]);backupJobs.value=b||[];migrationJobs.value=m||[];if(!selectedBackup.value||!backupJobs.value.some(x=>x.id===selectedBackup.value))selectedBackup.value=backupJobs.value[0]?.id||'';if(!selectedMigration.value||!migrationJobs.value.some(x=>x.id===selectedMigration.value))selectedMigration.value=migrationJobs.value[0]?.id||'';await Promise.all([loadSnapshots(),loadRuns()])}catch(e){pageError.value=e instanceof Error?e.message:'读取备份与迁移列表失败'}finally{loading.value=false}}
async function loadSnapshots(){const request=++snapshotsRequest;const jobId=selectedBackup.value;snapshotsError.value='';if(!jobId){snapshots.value=[];snapshotsLoading.value=false;return}snapshotsLoading.value=true;try{const result=await api.get<BackupSnapshot[]>(`/api/backups/snapshots?jobId=${encodeURIComponent(jobId)}`);if(request===snapshotsRequest&&selectedBackup.value===jobId)snapshots.value=result||[]}catch(e){if(request===snapshotsRequest&&selectedBackup.value===jobId){snapshots.value=[];snapshotsError.value=e instanceof Error?e.message:'读取本机快照失败'}}finally{if(request===snapshotsRequest)snapshotsLoading.value=false}}
async function loadRuns(){const request=++runsRequest;const jobId=selectedMigration.value;runsError.value='';if(!jobId){migrationRuns.value=[];runsLoading.value=false;return}runsLoading.value=true;try{const result=await api.get<MigrationRun[]>(`/api/migrations/runs?jobId=${encodeURIComponent(jobId)}`);if(request===runsRequest&&selectedMigration.value===jobId)migrationRuns.value=result||[]}catch(e){if(request===runsRequest&&selectedMigration.value===jobId){migrationRuns.value=[];runsError.value=e instanceof Error?e.message:'读取迁移运行记录失败'}}finally{if(request===runsRequest)runsLoading.value=false}}
function resetBackupForm(){backupEditId.value='';Object.assign(backupForm,{name:'',connectionId:eligible.value[0]?.id||'',localPath:'',remotePrefix:'',exclude:'',scheduleMinutes:0,retainRecent:10,retainDaily:7,retainMonthly:12,enabled:true});backupFormOpen.value=true}
function editBackup(j:BackupJob){backupEditId.value=j.id;Object.assign(backupForm,{name:j.name,connectionId:j.connectionId,localPath:j.localPath,remotePrefix:j.remotePrefix,exclude:(j.exclude||[]).join('\n'),scheduleMinutes:j.scheduleMinutes,retainRecent:j.retainRecent,retainDaily:j.retainDaily,retainMonthly:j.retainMonthly,enabled:j.enabled});backupFormOpen.value=true}
async function pickLocal(){busy.value='pick';try{const result=await api.post<{path:string}>('/api/pick-folder');if(result.path)backupForm.localPath=result.path}catch(e){notify(e instanceof Error?e.message:'选择本机目录失败')}finally{busy.value=''}}
async function saveBackup(){if(busy.value)return;busy.value='backup-save';try{const payload={id:backupEditId.value||undefined,name:backupForm.name.trim(),connectionId:backupForm.connectionId,localPath:backupForm.localPath,remotePrefix:backupForm.remotePrefix.trim().replace(/^\/+|\/+$/g,''),exclude:backupForm.exclude.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),scheduleMinutes:Number(backupForm.scheduleMinutes),retainRecent:Number(backupForm.retainRecent),retainDaily:Number(backupForm.retainDaily),retainMonthly:Number(backupForm.retainMonthly),enabled:backupForm.enabled};await api.post(backupEditId.value?'/api/backups/update':'/api/backups',payload);backupFormOpen.value=false;notify(backupEditId.value?'备份任务已更新':'备份任务已创建','success');backupPreview.value=null;await loadAll()}catch(e){notify(e instanceof Error?e.message:'保存备份任务失败')}finally{busy.value=''}}
async function previewBackup(j:BackupJob){busy.value='backup-preview:'+j.id;backupPreview.value=null;selectedBackup.value=j.id;try{backupPreview.value=await api.post<BackupPreview>('/api/backups/preview',{id:j.id});await loadSnapshots()}catch(e){notify(e instanceof Error?e.message:'生成备份预览失败')}finally{busy.value=''}}
function askBackupRestore(s:BackupSnapshot,remote=false){backupConfirm.value={kind:'restore',id:s.id,name:`${time(s.started)} · ${s.filesTotal} 个文件 · ${fmt(s.bytesTotal)}`,remote,connectionId:remote?remoteConnection.value:undefined,prefix:remote?remotePrefix.value:undefined}}
async function executeBackupConfirm(){const c=backupConfirm.value;if(!c||busy.value)return;busy.value='backup-action';try{if(c.kind==='delete'){await api.post('/api/backups/delete',{id:c.id});if(selectedBackup.value===c.id){selectedBackup.value='';backupPreview.value=null}notify('备份任务已删除','success')}else{const result=c.remote?await api.post<{path:string}>('/api/backups/restore-remote',{id:c.id,connectionId:c.connectionId,prefix:c.prefix}):await api.post<{path:string}>('/api/backups/restore',{id:c.id});notify(`快照已恢复到：${result.path}`,'success')}backupConfirm.value=null;await loadAll();if(c.remote)await loadRemoteSnapshots()}catch(e){notify(e instanceof Error?e.message:'备份操作失败；源数据保持不变')}finally{busy.value=''}}
async function runBackup(){if(!backupPreview.value||busy.value)return;busy.value='backup-run';try{const snapshot=await api.post<BackupSnapshot>('/api/backups/run',{id:backupPreview.value.jobId,token:backupPreview.value.token});lastBackupResult.value=snapshot;backupPreview.value=null;notify(snapshot.status==='complete'?'备份已完成':`备份结果：${statusLabel(snapshot.status)}`,snapshot.status==='complete'?'success':'info');await loadAll();await loadSnapshots()}catch(e){notify(e instanceof Error?e.message:'备份失败；请重新生成预览后重试')}finally{busy.value=''}}
function closeBackupCleanup(){backupCleanupTarget.value=null;backupCleanupPreview.value=null;backupCleanupResult.value=null;backupCleanupError.value=''}
async function previewBackupCleanup(snapshot:BackupSnapshot){
  if(busy.value)return
  backupCleanupTarget.value=snapshot;backupCleanupError.value='';backupCleanupPreview.value=null;backupCleanupResult.value=null;busy.value='backup-cleanup-preview'
  try{backupCleanupPreview.value=await api.post<BackupCleanupPreview>('/api/backups/cleanup-preview',{id:snapshot.id})}
  catch(e){backupCleanupError.value=e instanceof Error?e.message:'生成快照清理预览失败'}
  finally{busy.value=''}
}
async function runBackupCleanup(){
  const plan=backupCleanupPreview.value
  if(!plan||busy.value||backupCleanupResult.value||backupCleanupError.value)return
  busy.value='backup-cleanup'
  try{
    const result=await api.post<BackupCleanupResult>('/api/backups/cleanup',{id:plan.snapshotId,token:plan.token})
    backupCleanupResult.value=result
    if(result.status==='complete'){notify('不完整快照的远端残余已清理','success');closeBackupCleanup();await loadAll()}
    await loadSnapshots()
  }catch(e){backupCleanupError.value=e instanceof Error?e.message:'清理失败，请重新预览核对远端状态'}
  finally{busy.value=''}
}
async function repreviewBackupCleanup(){const target=backupCleanupTarget.value;if(target)await previewBackupCleanup(target)}
async function loadRemoteSnapshots(){if(!remoteConnection.value||!remotePrefix.value.trim()){remoteSnapshots.value=[];remoteError.value='请先选择连接并填写备份目录';return}remoteLoading.value=true;remoteError.value='';remoteSnapshots.value=[];try{const q=new URLSearchParams({connectionId:remoteConnection.value,prefix:remotePrefix.value.trim().replace(/^\/+|\/+$/g,'')});remoteSnapshots.value=await api.get<BackupSnapshot[]>(`/api/backups/remote-snapshots?${q}`)||[]}catch(e){remoteSnapshots.value=[];remoteError.value=e instanceof Error?e.message:'读取远端快照失败'}finally{remoteLoading.value=false}}
function resetMigrationForm(){migrationEditId.value='';Object.assign(migrationForm,{name:'',sourceConnection:eligible.value[0]?.id||'',sourcePrefix:'',targetConnection:eligible.value[1]?.id||eligible.value[0]?.id||'',targetPrefix:'',exclude:'',overwrite:false});migrationFormOpen.value=true}
function editMigration(j:MigrationJob){migrationEditId.value=j.id;Object.assign(migrationForm,{name:j.name,sourceConnection:j.sourceConnection,sourcePrefix:j.sourcePrefix,targetConnection:j.targetConnection,targetPrefix:j.targetPrefix,exclude:(j.exclude||[]).join('\n'),overwrite:j.overwrite});migrationFormOpen.value=true}
async function saveMigration(){if(busy.value)return;busy.value='migration-save';try{const payload={id:migrationEditId.value||undefined,name:migrationForm.name.trim(),sourceConnection:migrationForm.sourceConnection,sourcePrefix:migrationForm.sourcePrefix.trim().replace(/^\/+|\/+$/g,''),targetConnection:migrationForm.targetConnection,targetPrefix:migrationForm.targetPrefix.trim().replace(/^\/+|\/+$/g,''),exclude:migrationForm.exclude.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),overwrite:migrationForm.overwrite,enabled:true};await api.post(migrationEditId.value?'/api/migrations/update':'/api/migrations',payload);migrationFormOpen.value=false;migrationPreview.value=null;notify(migrationEditId.value?'迁移任务已更新':'迁移任务已创建','success');await loadAll()}catch(e){notify(e instanceof Error?e.message:'保存迁移任务失败')}finally{busy.value=''}}
async function previewMigration(j:MigrationJob){busy.value='migration-preview';selectedMigration.value=j.id;migrationPreview.value=null;try{migrationPreview.value=await api.post<MigrationPreview>('/api/migrations/preview',{id:j.id});await loadRuns()}catch(e){notify(e instanceof Error?e.message:'迁移预览失败')}finally{busy.value=''}}
async function askMigration(action:'delete'|'start'|'cancel'|'cleanup',id:string,name:string){if(action==='cleanup'){busy.value='cleanup-preview';cleanupPreview.value=null;try{cleanupPreview.value=await api.post<CleanupPreview>('/api/migrations/cleanup-preview',{id});migrationConfirm.value={kind:'cleanup',id,name}}catch(e){notify(e instanceof Error?e.message:'源清理预览失败')}finally{busy.value=''}return}migrationConfirm.value={kind:action,id,name}}
async function executeMigrationConfirm(){const c=migrationConfirm.value;if(!c||busy.value)return;busy.value='migration-action';try{if(c.kind==='delete'){await api.post('/api/migrations/delete',{id:c.id});migrationPreview.value=null;notify('迁移任务已删除','success')}else if(c.kind==='start'){if(!migrationPreview.value||migrationPreview.value.jobId!==c.id)throw new Error('迁移预览已失效，请重新预览');await api.post('/api/migrations/start',{id:c.id,token:migrationPreview.value.token});migrationPreview.value=null;notify('迁移已加入后台队列','success')}else if(c.kind==='cancel'){await api.post('/api/migrations/cancel',{id:c.id});notify('已请求取消迁移；已完成文件不会回滚','success')}else{if(!cleanupPreview.value||cleanupPreview.value.runId!==c.id)throw new Error('源清理预览已失效，请重新预览');await api.post('/api/migrations/cleanup',{id:c.id,token:cleanupPreview.value.token});cleanupPreview.value=null;notify('预览中的源文件已清理','success')}migrationConfirm.value=null;await loadAll()}catch(e){notify(e instanceof Error?e.message:'迁移操作失败')}finally{busy.value=''}}
async function resumeMigration(r:MigrationRun){busy.value='resume:'+r.id;try{await api.post('/api/migrations/resume',{id:r.id});notify('迁移已恢复','success');await loadRuns()}catch(e){notify(e instanceof Error?e.message:'恢复迁移失败')}finally{busy.value=''}}
function selectBackup(id:string){selectedBackup.value=id;backupPreview.value=null;snapshots.value=[];void loadSnapshots()}
function selectMigration(id:string){selectedMigration.value=id;migrationPreview.value=null;migrationRuns.value=[];void loadRuns()}
let runsTimer:number|undefined
onMounted(()=>{void loadAll();remoteConnection.value=eligible.value[0]?.id||'';runsTimer=window.setInterval(()=>{if(document.visibilityState==='visible'&&migrationRuns.value.some(r=>['queued','running','cancel_requested'].includes(r.state)))void loadRuns()},2000)})
onBeforeUnmount(()=>{if(runsTimer)window.clearInterval(runsTimer)})
</script>

<template>
  <div class="page-view backup-migration-page">
    <header class="page-heading"><div><h1>备份与迁移</h1></div><button class="button secondary" :disabled="loading" @click="loadAll"><RefreshCw :size="15" :class="{spin:loading}"/>刷新</button></header>
    <p v-if="eligible.some(c=>c.kind==='demo')" class="preview-warning demo-notice"><ShieldAlert :size="16"/>演示空间在退出后清空，请勿保存正式备份。</p>
    <nav class="operation-tabs"><button :class="{active:tab==='backup'}" :aria-pressed="tab==='backup'" @click="tab='backup'"><Archive :size="15"/>备份与恢复</button><button :class="{active:tab==='migration'}" :aria-pressed="tab==='migration'" @click="tab='migration'"><ArrowRightLeft :size="15"/>存储迁移</button></nav>
    <div v-if="pageError" class="workflow-error"><AlertCircle :size="16"/><span>{{pageError}}</span><button class="button secondary small" @click="loadAll">重试</button></div>
    <template v-if="tab==='backup'">
      <div class="section-heading"><div><h2><Archive :size="17"/>备份任务</h2></div><button class="button primary small" :disabled="!eligible.length" @click="resetBackupForm"><Plus :size="15"/>新建备份</button></div>
      <div v-if="loading" class="workflow-empty squirrel-inline-loading" role="status"><SquirrelMark variant="eat" :size="34"/><span>正在读取备份任务…</span></div>
      <div v-else-if="backupJobs.length" class="backup-job-layout"><aside class="backup-job-list"><button v-for="job in backupJobs" :key="job.id" class="backup-job-select" :class="{active:selectedBackup===job.id}" :aria-pressed="selectedBackup===job.id" @click="selectBackup(job.id)"><span><b>{{job.name}}</b><small>{{connName(job.connectionId)}} · {{job.remotePrefix}}</small></span><span class="status-pill" :class="statusClass(job.status||'ready')"><i></i>{{statusLabel(job.status||'ready')}}</span></button></aside><section v-if="selectedJob" class="backup-detail card-panel"><div class="detail-title"><div><h2>{{selectedJob.name}}</h2><p>{{selectedJob.localPath}} → {{selectedJob.remotePrefix}}</p></div><span class="status-pill" :class="selectedJob.scheduleMinutes>0&&selectedJob.enabled?'green':'gray'"><i></i>{{selectedJob.scheduleMinutes>0?(selectedJob.enabled?'定时已启用':'定时已暂停'):'手动执行'}}</span></div><div class="backup-facts"><span>连接 <b>{{connName(selectedJob.connectionId)}}</b></span><span>保留策略 <b>最近 {{selectedJob.retainRecent}} · 日 {{selectedJob.retainDaily}} · 月 {{selectedJob.retainMonthly}}</b></span><span>上次运行 <b>{{time(selectedJob.lastRun)}}</b></span><span>计划 <b>{{selectedJob.scheduleMinutes?`${selectedJob.scheduleMinutes} 分钟`:'手动'}}</b></span></div><p v-if="selectedJob.detail" class="inline-error"><AlertCircle :size="14"/>{{selectedJob.detail}}</p><div class="detail-actions"><button class="button primary small" :disabled="busy!==''" @click="previewBackup(selectedJob)"><ShieldAlert :size="14"/>{{busy==='backup-preview:'+selectedJob.id?'生成预览…':'预览本次备份'}}</button><details class="tool-disclosure inline-more"><summary>更多操作</summary><div class="inline-more-actions"><button class="button secondary small" @click="editBackup(selectedJob)">编辑</button><button class="button subtle small danger-text" @click="backupConfirm={kind:'delete',id:selectedJob.id,name:selectedJob.name}"><Trash2 :size="14"/>删除</button></div></details></div>
        <div v-if="backupPreview" class="preview-box"><div class="preview-heading"><div><b>备份预览</b><small>生成于 {{time(backupPreview.created)}} · 排除 {{backupPreview.excluded}} 项</small></div><span>{{backupPreview.files.length}} 个文件 · {{fmt(backupPreview.bytes)}}</span></div><div class="preview-file-list"><div v-for="f in backupPreview.files" :key="f.path" class="preview-file"><div class="preview-file-main"><code>{{f.path}}</code><details class="technical-detail"><summary>校验值</summary><code>SHA-256 {{f.sha256}}</code></details></div><span>{{fmt(f.size)}}</span><span class="status-pill" :class="statusClass(f.state)"><i></i>{{statusLabel(f.state)}}</span></div><div v-if="!backupPreview.files.length" class="workflow-empty compact">没有符合条件的文件。</div></div><footer class="modal-actions"><button class="button secondary" :disabled="busy!==''" @click="backupPreview=null">放弃预览</button><button class="button primary" :disabled="busy!==''||!canRunBackup" @click="runBackup"><LoaderCircle v-if="busy==='backup-run'" :size="14" class="spin"/><Check v-else :size="14"/>{{busy==='backup-run'?'备份中…':'确认并运行备份'}}</button></footer></div>
        <div v-if="lastBackupResult?.jobId===selectedBackup" class="backup-result"><div class="preview-heading"><div><b>最近运行结果</b><small>{{time(lastBackupResult.completed)}} · {{lastBackupResult.filesDone}} 完成 / {{lastBackupResult.filesFailed}} 失败</small></div><span class="status-pill" :class="statusClass(lastBackupResult.status)"><i></i>{{statusLabel(lastBackupResult.status)}}</span></div><p v-if="lastBackupResult.error" class="inline-error-text">{{lastBackupResult.error}}</p><div class="preview-file-list"><div v-for="f in lastBackupResult.files||[]" :key="f.path" class="preview-file"><div class="preview-file-main"><code>{{f.path}}</code><details v-if="f.sha256" class="technical-detail"><summary>校验值</summary><code>SHA-256 {{f.sha256}}</code></details><small v-if="f.error" class="inline-error-text">{{f.error}}</small></div><span>{{fmt(f.size)}}</span><span class="status-pill" :class="statusClass(f.state)"><i></i>{{statusLabel(f.state)}}</span></div></div></div>
      </section></div>
      <div v-else class="workflow-empty">暂无备份任务。</div>
      <section v-if="selectedJob" class="settings-section backup-snapshots"><div class="section-heading"><div><h2><Clock3 :size="17"/>备份记录</h2></div><button class="icon-button" :disabled="snapshotsLoading" title="刷新备份记录" @click="loadSnapshots"><RefreshCw :size="15" :class="{spin:snapshotsLoading}"/></button></div><div v-if="snapshotsLoading&&!snapshots.length" class="workflow-empty compact squirrel-inline-loading" role="status"><SquirrelMark variant="eat" :size="28"/><span>正在读取快照…</span></div><div v-else-if="snapshotsError" class="workflow-error"><AlertCircle :size="15"/><span>{{snapshotsError}}</span><button class="button secondary small" @click="loadSnapshots">重试</button></div><div v-else-if="snapshots.length" class="snapshot-list"><article v-for="s in snapshots" :key="s.id" class="snapshot-row"><div><b>{{time(s.started)}}</b><small>{{s.filesDone}} / {{s.filesTotal}} 个文件 · {{fmt(s.bytesTotal)}}</small><details class="technical-detail"><summary>快照标识</summary><code>{{s.id}}</code></details><small v-if="s.error" class="inline-error-text">{{s.error}}</small></div><span class="status-pill" :class="statusClass(s.status)"><i></i>{{statusLabel(s.status)}}</span><button v-if="['partial','failed','error','paused','cancelled'].includes(s.status)" class="button secondary small" :disabled="busy!==''" @click="previewBackupCleanup(s)"><LoaderCircle v-if="busy==='backup-cleanup-preview'" :size="14" class="spin"/><Trash2 v-else :size="14"/>{{busy==='backup-cleanup-preview'?'检查对象…':'预览清理'}}</button><button class="button secondary small" :disabled="s.filesDone===0||s.status==='cleaned'" @click="askBackupRestore(s)"><FolderOpen :size="14"/>恢复到新目录</button></article></div><div v-else class="workflow-empty compact">没有备份记录。</div></section>
      <details class="tool-disclosure remote-snapshots"><summary>从其他设备的备份恢复</summary><div class="remote-restore-body"><div class="remote-query"><label class="field"><span>远端连接</span><select v-model="remoteConnection"><option v-for="c in eligible" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field"><span>备份目录</span><input v-model="remotePrefix" placeholder="例如：archive/workstation"/></label><button class="button secondary" :disabled="remoteLoading" @click="loadRemoteSnapshots"><RefreshCw :size="14" :class="{spin:remoteLoading}"/>扫描快照</button></div><div v-if="remoteError" class="workflow-error"><AlertCircle :size="15"/><span>{{remoteError}}</span><button class="button secondary small" :disabled="remoteLoading" @click="loadRemoteSnapshots">重试</button></div><div v-else-if="remoteSnapshots.length" class="snapshot-list"><article v-for="s in remoteSnapshots" :key="s.id" class="snapshot-row"><div><b>{{time(s.started)}}</b><small>{{s.filesDone}} / {{s.filesTotal}} 个文件 · {{fmt(s.bytesTotal)}}</small><details class="technical-detail"><summary>快照标识</summary><code>{{s.id}}</code></details></div><span class="status-pill" :class="statusClass(s.status)"><i></i>{{statusLabel(s.status)}}</span><button class="button secondary small" :disabled="s.filesDone===0||s.status==='cleaned'" @click="askBackupRestore(s,true)"><FolderOpen :size="14"/>恢复到新目录</button></article></div><div v-else-if="remoteLoading" class="workflow-empty compact">正在扫描远端快照…</div><div v-else class="workflow-empty compact">扫描远端以发现可恢复快照。</div></div></details>
    </template>

    <template v-else>
      <div class="section-heading"><div><h2><ArrowRightLeft :size="17"/>迁移任务</h2><p>迁移会复制并核验目标内容；源文件保留，除非你在迁移完成后单独预览并确认清理。</p></div><button class="button primary small" :disabled="eligible.length<1" @click="resetMigrationForm"><Plus :size="15"/>新建迁移</button></div>
      <div v-if="migrationJobs.length" class="migration-job-list"><article v-for="job in migrationJobs" :key="job.id" class="migration-job card-panel" :class="{active:selectedMigration===job.id}"><div class="detail-title"><div><h2>{{job.name}}</h2><p>{{connName(job.sourceConnection)}}:/{{job.sourcePrefix}} <ChevronDown :size="13"/> {{connName(job.targetConnection)}}:/{{job.targetPrefix}}</p><small v-if="job.exclude?.length" class="exclude-summary">排除：{{job.exclude.join(' · ')}}</small></div><span class="status-pill" :class="job.enabled?'green':'gray'"><i></i>{{job.enabled?'启用':'暂停'}}</span></div><div class="detail-actions"><button class="button primary small" :disabled="busy!==''" @click="previewMigration(job)"><ShieldAlert :size="14"/>{{busy==='migration-preview'&&selectedMigration===job.id?'生成预览…':'生成迁移预览'}}</button><details class="tool-disclosure inline-more"><summary>更多操作</summary><div class="inline-more-actions"><button class="button secondary small" @click="editMigration(job)">编辑</button><button class="button subtle small danger-text" @click="askMigration('delete',job.id,job.name)"><Trash2 :size="14"/>删除任务</button></div></details></div><div v-if="migrationPreview?.jobId===job.id" class="preview-box"><div class="preview-heading"><div><b>迁移预览</b><small>生成于 {{time(migrationPreview.created)}} · 冲突 {{migrationPreview.conflicts}} 项</small></div><span>{{migrationPreview.sourceFiles}} 个文件 · {{fmt(migrationPreview.bytes)}}</span></div><div class="migration-items"><div v-for="item in migrationPreview.items" :key="item.sourcePath" class="migration-item"><div><code>{{item.sourcePath}}</code><span class="migration-arrow">→</span><code>{{item.targetPath}}</code><small>{{fmt(item.sourceSize)}} · {{item.destAbsent?'目标不存在':'目标已存在'}}</small><details class="technical-detail"><summary>版本信息</summary><code>来源 ETag {{item.sourceEtag||'未知'}} · 目标 ETag {{item.destAbsent?'—':item.destBeforeEtag||'未知'}}</code></details><small v-if="item.error" class="inline-error-text">{{item.error}}</small></div><span class="status-pill" :class="statusClass(item.state)"><i></i>{{migrationItemLabel(item.state)}}</span></div><div v-if="!migrationPreview.items.length" class="workflow-empty compact">预览中没有可迁移文件。</div></div><p class="preview-warning"><AlertCircle :size="14"/>开始前服务会重新核对源和目标版本。{{job.overwrite?'此任务允许覆盖预览中标记的目标文件。':'此任务不会覆盖已存在目标。'}}</p><footer class="modal-actions"><button class="button secondary" @click="migrationPreview=null">丢弃预览</button><button class="button primary" :disabled="busy!==''||migrationPreview.items.length===0" @click="askMigration('start',job.id,job.name)"><ArrowRightLeft :size="14"/>确认并开始迁移</button></footer></div></article></div><div v-else class="workflow-empty">尚无迁移任务。</div>
      <section class="settings-section migration-runs"><div class="section-heading"><div><h2><Clock3 :size="17"/>迁移运行记录</h2><p>取消只停止后续文件，不会撤销已经完成的复制。</p></div><button class="icon-button" :disabled="runsLoading" title="刷新运行状态" @click="loadRuns"><RefreshCw :size="15" :class="{spin:runsLoading}"/></button></div><div v-if="runsLoading&&!migrationRuns.length" class="workflow-empty compact">正在读取运行记录…</div><div v-else-if="runsError" class="workflow-error"><AlertCircle :size="15"/><span>{{runsError}}</span><button class="button secondary small" @click="loadRuns">重试</button></div><div v-else-if="migrationRuns.length" class="migration-run-list"><article v-for="run in migrationRuns" :key="run.id" class="migration-run"><div class="run-main"><div><b>{{statusLabel(run.state)}}</b><details class="technical-detail"><summary>运行标识</summary><code>{{run.id}}</code></details></div><small>{{time(run.started)}} · 已完成 {{run.filesDone}} / {{run.filesTotal}} · 失败 {{run.filesFailed}}</small><small v-if="run.detail">{{run.detail}}</small><small v-if="run.state==='uncertain'" class="inline-error-text">先到“活动 → 维护记录 → 未决操作”核对本次操作结果，再恢复迁移；系统不会自动重放未知提交。</small><div class="meter-track"><div class="meter-fill purple" :style="{width:`${migrationProgress(run)}%`}"></div></div></div><div class="detail-actions"><button v-if="['failed','cancelled','partial','paused','uncertain'].includes(run.state)" class="button secondary small" :disabled="busy!==''" @click="resumeMigration(run)"><RotateCcw :size="14"/>{{busy==='resume:'+run.id?'恢复中…':'恢复'}}</button><button v-if="['queued','running'].includes(run.state)" class="button subtle small danger-text" :disabled="busy!==''" @click="askMigration('cancel',run.id,`运行于 ${time(run.started)}`)"><X :size="14"/>请求取消</button><button v-if="['complete','partial'].includes(run.state)" class="button secondary small" :disabled="busy!==''" @click="askMigration('cleanup',run.id,`运行于 ${time(run.started)}`)"><Trash2 :size="14"/>预览源清理</button></div></article></div><div v-else class="workflow-empty compact">当前任务暂无运行记录。</div></section>
    </template>

    <BaseModal v-model="backupFormOpen" :dismissible="busy===''" :title="backupEditId?'编辑备份任务':'新建备份任务'" subtitle="快照保存在远端，保留本机原文件。" width="620px"><form class="form-stack" @submit.prevent="saveBackup"><label class="field"><span>任务名称</span><input v-model="backupForm.name" required maxlength="80"/></label><label class="field"><span>本机来源目录</span><div class="inline-input"><input v-model="backupForm.localPath" required placeholder="选择要保护的目录"/><button type="button" class="button secondary small" :disabled="busy==='pick'" @click="pickLocal"><FolderOpen :size="14"/>选择</button></div></label><label class="field"><span>远端连接</span><select v-model="backupForm.connectionId" required><option v-for="c in eligible" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field"><span>备份目录</span><input v-model="backupForm.remotePrefix" required placeholder="例如：backups/office"/><small class="field-hint">不能选择存储根目录；应用会在此位置创建自己的快照目录。</small></label><details class="tool-disclosure"><summary>计划与保留设置</summary><div class="form-stack"><label class="field"><span>排除规则（每行一条）</span><textarea v-model="backupForm.exclude" rows="3" placeholder="例如：*.tmp"></textarea></label><div class="form-row"><label class="field"><span>计划间隔（分钟，0 为手动）</span><input v-model.number="backupForm.scheduleMinutes" type="number" min="0" max="525600"/></label><label class="field"><span>保留最近快照</span><input v-model.number="backupForm.retainRecent" type="number" min="0" max="1000"/></label></div><div class="form-row"><label class="field"><span>每日保留数</span><input v-model.number="backupForm.retainDaily" type="number" min="0" max="1000"/></label><label class="field"><span>每月保留数</span><input v-model.number="backupForm.retainMonthly" type="number" min="0" max="1000"/></label></div><label class="check-row"><input v-model="backupForm.enabled" type="checkbox"/><span>启用计划备份</span></label></div></details><footer class="modal-actions"><button type="button" class="button secondary" :disabled="busy!==''" @click="backupFormOpen=false">取消</button><button class="button primary" type="submit" :disabled="busy!==''||!backupForm.localPath"><LoaderCircle v-if="busy==='backup-save'" :size="14" class="spin"/>{{busy==='backup-save'?'保存中…':'保存任务'}}</button></footer></form></BaseModal>
    <BaseModal v-model="migrationFormOpen" :dismissible="busy===''" :title="migrationEditId?'编辑迁移任务':'新建迁移任务'" subtitle="选择来源和目标目录。保存后先生成完整文件预览。" width="620px"><form class="form-stack" @submit.prevent="saveMigration"><label class="field"><span>任务名称</span><input v-model="migrationForm.name" required maxlength="80"/></label><div class="form-row"><label class="field"><span>来源连接</span><select v-model="migrationForm.sourceConnection" required><option v-for="c in eligible" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field"><span>来源目录</span><input v-model="migrationForm.sourcePrefix" placeholder="留空表示连接根目录"/></label></div><div class="form-row"><label class="field"><span>目标连接</span><select v-model="migrationForm.targetConnection" required><option v-for="c in migrationTargets" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="field"><span>目标目录</span><input v-model="migrationForm.targetPrefix" placeholder="例如：archive/project"/></label></div><details class="tool-disclosure"><summary>高级设置</summary><div class="form-stack"><label class="field"><span>排除规则（每行一条）</span><textarea v-model="migrationForm.exclude" rows="3" placeholder="例如：*.tmp"/></label><label class="check-row"><input v-model="migrationForm.overwrite" type="checkbox"/><span>允许覆盖目标中已存在的文件（仅按本次预览版本写入）</span></label></div></details><footer class="modal-actions"><button type="button" class="button secondary" :disabled="busy!==''" @click="migrationFormOpen=false">取消</button><button class="button primary" type="submit" :disabled="busy!==''"><LoaderCircle v-if="busy==='migration-save'" :size="14" class="spin"/>保存迁移任务</button></footer></form></BaseModal>
    <BaseModal :model-value="!!backupConfirm" :dismissible="busy===''" :title="backupConfirm?.kind==='delete'?'删除备份任务':'恢复快照到新目录'" :subtitle="backupConfirm?.name||''" @update:model-value="v=>{if(!v)backupConfirm=null}"><div class="confirm-panel"><div class="confirm-warning"><AlertCircle :size="18"/></div><p v-if="backupConfirm?.kind==='delete'">仅删除任务配置，不会清除远端快照，也不会删除本机源文件。</p><p v-else>确认后将打开本机目录选择器，并在所选父目录创建新的独立恢复目录。不会覆盖已有目录。</p><details class="technical-detail"><summary>操作标识</summary><code>{{backupConfirm?.id}}</code></details><footer class="modal-actions"><button class="button secondary" :disabled="busy!==''" @click="backupConfirm=null">返回</button><button class="button danger" :disabled="busy!==''" @click="executeBackupConfirm">{{busy==='backup-action'?'处理中…':backupConfirm?.kind==='delete'?'确认删除任务':'选择目录并恢复'}}</button></footer></div></BaseModal>
    <BaseModal :model-value="!!migrationConfirm" :dismissible="busy===''" :title="migrationConfirm?.kind==='delete'?'删除迁移任务':migrationConfirm?.kind==='start'?'确认开始迁移':migrationConfirm?.kind==='cancel'?'请求取消迁移':'确认清理源文件'" :subtitle="migrationConfirm?.name||''" @update:model-value="v=>{if(!v){migrationConfirm=null;cleanupPreview=null}}" width="640px"><div v-if="migrationConfirm" class="confirm-panel"><div class="confirm-warning"><AlertCircle :size="18"/></div><template v-if="migrationConfirm.kind==='cleanup'"><p>下面这些源路径将被删除。服务会再次核验源 ETag/内容与目标 ETag/内容；任何一项不匹配都会停止并保留剩余源文件。</p><div class="cleanup-list"><div v-for="item in cleanupPreview?.items||[]" :key="item.sourcePath"><code>{{item.sourcePath}}</code><span>→ {{item.targetPath}}</span><small>{{fmt(item.sourceSize)}} · 源 SHA-256 {{item.sourceHash||'—'}} · 目标 ETag {{item.destEtag||'—'}}</small></div><div v-if="cleanupPreview&&!cleanupPreview.items.length" class="workflow-empty compact">没有可安全清理的源文件。</div></div></template><p v-else-if="migrationConfirm.kind==='start'">服务会重新核验预览中的全部源和目标版本后开始后台迁移。目标已变化时会拒绝按旧预览写入；源文件保留。</p><p v-else-if="migrationConfirm.kind==='cancel'">只取消后续处理，已完成的目标文件会保留，源文件不会自动删除。</p><p v-else>仅移除此迁移任务的配置，不会删除源或目标文件。</p><footer class="modal-actions"><button class="button secondary" :disabled="busy!==''" @click="migrationConfirm=null;cleanupPreview=null">返回</button><button class="button danger" :disabled="busy!==''||(migrationConfirm.kind==='cleanup'&&!cleanupPreview?.items.length)" @click="executeMigrationConfirm">{{busy==='migration-action'?'处理中…':migrationConfirm.kind==='cleanup'?'确认清理以上源文件':migrationConfirm.kind==='start'?'确认并开始':'确认操作'}}</button></footer></div></BaseModal>
    <BaseModal :model-value="!!backupCleanupTarget" :dismissible="busy===''" title="清理不完整快照" :subtitle="backupCleanupTarget ? time(backupCleanupTarget.started) : ''" width="640px" @update:model-value="v=>{if(!v)closeBackupCleanup()}">
      <div class="backup-cleanup-review"><details v-if="backupCleanupTarget" class="technical-detail"><summary>快照标识</summary><code>{{backupCleanupTarget.id}}</code></details>
        <div v-if="busy==='backup-cleanup-preview'" class="workflow-empty squirrel-inline-loading" role="status"><SquirrelMark variant="eat" :size="40"/><span>正在核对快照文件与远端内容…</span></div>
        <div v-if="backupCleanupError" class="workflow-error" role="alert"><AlertCircle :size="16"/><span>{{backupCleanupError}}</span></div>
        <template v-if="backupCleanupPreview">
          <p class="preview-warning"><ShieldAlert :size="16"/><span>清理这个不完整快照中的远端文件和清单。本机来源文件保留；完整快照继续保留。下列文件的版本若有变化，清理会停止。</span></p>
          <div class="preview-heading"><b>{{backupCleanupPreview.objects.length}} 个远端对象 · {{fmt(backupCleanupPreview.bytes)}}</b><small>预览有效期 15 分钟</small></div>
          <div class="cleanup-list" aria-label="本次清理的快照内路径"><div v-for="object in backupCleanupPreview.objects" :key="object.path"><code>{{object.path}}</code><small>{{object.kind==='manifest'?'快照清单':'备份文件'}} · {{fmt(object.size)}}</small></div><div v-if="!backupCleanupPreview.objects.length" class="workflow-empty compact">没有剩余远端对象，可完成本次清理检查。</div></div>
          <div v-if="backupCleanupResult" class="cleanup-result" role="status"><b>{{backupCleanupResult.status==='nothing_to_clean'?'没有可清理的对象':'清理尚未全部完成'}}</b><p>本次已清理 {{backupCleanupResult.deleted.length}} 项；仍需核对 {{backupCleanupResult.remaining.length}} 项。</p><p v-for="message in backupCleanupResult.errors" :key="message" class="inline-error-text">{{message}}</p><code v-for="key in backupCleanupResult.remaining" :key="key">{{key}}</code></div>
        </template>
        <footer class="modal-actions"><button class="button secondary" :disabled="busy!==''" @click="closeBackupCleanup">关闭</button><button v-if="backupCleanupError||backupCleanupResult" class="button secondary" :disabled="busy!==''" @click="repreviewBackupCleanup"><RefreshCw :size="14"/>重新预览</button><button v-else-if="backupCleanupPreview" class="button danger" :disabled="busy!==''" @click="runBackupCleanup"><LoaderCircle v-if="busy==='backup-cleanup'" :size="14" class="spin"/>{{busy==='backup-cleanup'?'正在清理…':backupCleanupPreview.objects.length?'确认清理这些对象':'完成清理检查'}}</button></footer>
      </div>
    </BaseModal>

  </div>
</template>

<style scoped>
